import{describe,it,expect}from"vitest";import{AWARD_ENCYCLOPEDIA,getAwardDetailsByKey,searchAwardsAndRecipients,filterAwardsByCategory}from"../../frontend/js-modules/national-awards.js";describe("Vishisht Seva Medal Explorer Dataset",()=>{it("contains the 'vishisht-seva-medal' dataset entry",()=>{const e=AWARD_ENCYCLOPEDIA["vishisht-seva-medal"];expect(e).toBeDefined(),expect(e.id).toBe("vishisht-seva-medal"),expect(e.name).toContain("Vishisht Seva Medal"),expect(e.category).toBe("gallantry"),expect(e.establishedYear).toBe("1960")}),it("contains all required dataset sections (Eligibility, History, Medal Design, Winners, Facts)",()=>{const e=getAwardDetailsByKey("vishisht-seva-medal");expect(e).not.toBeNull(),expect(e.eligibility).toBeTruthy(),expect(e.history).toBeTruthy(),expect(e.medalDesign).toBeTruthy(),expect(Array.isArray(e.notableWinners)).toBe(!0),expect(e.notableWinners.length).toBeGreaterThanOrEqual(4),expect(Array.isArray(e.interestingFacts)).toBe(!0),expect(e.interestingFacts.length).toBeGreaterThanOrEqual(3)}),it("includes notable military leaders across Army, Navy, and Air Force in dataset",()=>{const e=getAwardDetailsByKey("vishisht-seva-medal").notableWinners.map(e=>e.name);expect(e.some(e=>e.includes("Naravane"))).toBe(!0),expect(e.some(e=>e.includes("Rodrigues"))).toBe(!0),expect(e.some(e=>e.includes("Dhanoa"))).toBe(!0),expect(e.some(e=>e.includes("Cardozo"))).toBe(!0)}),it("searches and filters Vishisht Seva Medal accurately",()=>{const e=searchAwardsAndRecipients("Vishisht Seva Medal");expect(e.length).toBeGreaterThanOrEqual(1),expect(e.some(e=>"vishisht-seva-medal"===e.id)).toBe(!0);const t=searchAwardsAndRecipients("Cardozo");expect(t.length).toBeGreaterThanOrEqual(1),expect(t[0].id).toBe("vishisht-seva-medal");const a=filterAwardsByCategory("gallantry");expect(a.some(e=>"vishisht-seva-medal"===e.id)).toBe(!0)})});